from pathlib import Path
import json,statistics as st
p=Path(__file__).resolve().parent;t=json.loads((p/'timing-summary.json').read_text())['timed'];score={n:[min(r['directions'][d]['gain_percent'] for r in t[n].values() for d in ['forward','reverse']),st.mean(r['gain_percent'] for r in t[n].values())] for n in ['pack4_quad_fb23','pack4_quad_clean'] if n in t and all(r['quality_pass'] for r in t[n].values())};assert score;best=sorted(score,key=lambda n:(-score[n][0],-score[n][1],n))[0];joint='joint_A_B_'+best;ts=json.loads((p/'timing-candidates.json').read_text());assert joint not in ts;ts.append(joint);(p/'timing-candidates.json').write_text(json.dumps(ts,indent=2)+'\n');(p/'joint-selection.json').write_text(json.dumps({'scores_min_direction_then_mean':score,'best_quad':best,'joint':joint,'fixed_A':'pack4_fb0_nopre','fixed_B':'pack4_fb1_clean','all_joints_prebuilt_before_smoke_and_timing':True},indent=2)+'\n');print('selected',joint)
